import System.Exception;import System.ArgumentException;import System.ArgumentOutOfRangeException;import System.Globalization.NumberFormatInfo;import System.Type;import System.Globalization.DigitShapes;import java.nio.file.*;import java.util.*;
class NumberFormatInfoDigitSubstitutionProbe {
 interface Action{void run();}
 static String units(String s){if(s==null)return "~";StringJoiner j=new StringJoiner(",");for(char c:s.toCharArray())j.add(Integer.toString(c));return j.toString();}
 static String text(String s){if(s.equals("~"))return null;StringBuilder b=new StringBuilder();if(!s.isEmpty())for(String u:s.split(","))b.append((char)Integer.parseInt(u));return b.toString();}
 static int[] sizes(String s){if(s.equals("~"))return null;if(s.isEmpty())return new int[0];String[] p=s.split(",");int[] a=new int[p.length];for(int i=0;i<a.length;i++)a[i]=Integer.parseInt(p[i]);return a;}
 static String csv(int[] a){StringJoiner j=new StringJoiner(",");for(int v:a)j.add(Integer.toString(v));return j.toString();}
 static String outcome(Action a){try{a.run();return "OK";}catch(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),e instanceof ArgumentOutOfRangeException x&&x.get_ActualValue()!=null?x.get_ActualValue().toString():"~");}}
 static void check(String a,String e,String c){if(!a.equals(e))throw new AssertionError(c+" actual="+a+" expected="+e);}
 static String flag(boolean b){return b?"1":"0";}
 static String enumText(DigitShapes value,String f){try{return "OK|"+units(value.ToString(f));}catch(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),"~");}}
 public static void main(String[] args)throws java.lang.Exception{int setters=0,enums=0,groups=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);if(p[0].equals("T")){Type t=Type.GetType("System.Globalization.DigitShapes");List<String> actual=List.of(t.get_FullName(),t.get_Name(),t.get_Namespace(),t.get_BaseType().get_FullName(),flag(t.get_IsEnum()),flag(t.get_IsValueType()),flag(t.get_IsPrimitive()),flag(t.get_IsSealed()),t.GetEnumUnderlyingType().get_FullName(),String.join(",",t.GetEnumNames()),String.join(",",Arrays.stream(t.GetEnumValues()).map(v->Integer.toString(((DigitShapes)v).get_Value())).toList()));for(int i=0;i<actual.size();i++)check(actual.get(i),p[i+1],"DigitShapes type "+i);groups+=11;continue;}if(p[0].equals("E")){check(enumText(DigitShapes.FromInt32(Integer.parseInt(p[1])),text(p[2])),p[3],"enum format "+line);enums++;groups++;continue;}int value=Integer.parseInt(p[1]),seed=Integer.parseInt(p[2]);NumberFormatInfo original=new NumberFormatInfo();original.set_DigitSubstitution(DigitShapes.FromInt32(seed));NumberFormatInfo ro=NumberFormatInfo.ReadOnly(original),target=switch(p[3]){case "mutable"->original;case "readonly"->ro;case "clone"->(NumberFormatInfo)ro.Clone();case "invariant"->NumberFormatInfo.get_InvariantInfo();default->throw new AssertionError();};List<String> actual=new ArrayList<>();actual.add(Integer.toString(target.get_DigitSubstitution().get_Value()));actual.add(outcome(()->target.set_DigitSubstitution(DigitShapes.FromInt32(value))));NumberFormatInfo clone=(NumberFormatInfo)target.Clone(),view=NumberFormatInfo.ReadOnly(target);for(NumberFormatInfo n:new NumberFormatInfo[]{target,original,clone,view})actual.add(Integer.toString(n.get_DigitSubstitution().get_Value()));actual.add(flag(target.get_IsReadOnly()));actual.add(flag(clone.get_IsReadOnly()));actual.add(flag(view.get_IsReadOnly()));if(actual.size()!=9||p.length!=13)throw new AssertionError();for(int i=0;i<actual.size();i++)check(actual.get(i),p[4+i],"setter "+line);groups+=9;setters++;}java.lang.System.out.println("PASS DigitShapes setters="+setters+" enumFormats="+enums+" groups="+groups);}
}
